/**
 * The map of the 212 kept papers: one citation network in four named topics, the same in every
 * picture. Its coordinates are generated by tools/layouts.mjs into network.data.js; this module
 * adds what depends on where a picture places the topics: the citations between them.
 */
import { TOPICS } from './network.data.js';

/**
 * @typedef {object} Node A paper, measured from the middle of its topic's own network.
 * @property {number} i Its index in the topic.
 * @property {number} x
 * @property {number} y
 * @property {number} r Its radius: larger the more it is cited.
 * @property {number} deg How many citations it has in the topic.
 * @property {string} [seed] The seed paper's name, on the one seed of a topic.
 */
/**
 * @typedef {object} Topic
 * @property {string} name
 * @property {number} n How many papers it holds.
 * @property {string} [seed] The name of its seed paper.
 * @property {number} w The width of its own network.
 * @property {number} h Its height.
 * @property {Node[]} nodes
 * @property {[number, number][]} links Its citations, as pairs of node indices.
 */

/** The four topics. */
export const topics = TOPICS;

/** Neighbouring topics, and how many citations cross between them. */
const PAIRS = [
  [0, 1, 2],
  [1, 2, 2],
  [2, 3, 2],
];

/**
 * Picks the citations between neighbouring topics for one placement of the map: single lines
 * between papers on the facing sides, apart from each other and clear of other papers.
 *
 * @param {{ x: number, y: number }[]} at Where the middle of each topic's network stands.
 * @param {number} s The map's scale.
 * @returns {[number, number, number, number][]} Each as [topic, node, topic, node].
 */
export function between(at, s) {
  /** @type {[number, number, number, number][]} */
  const out = [];
  for (const [ta, tb, many] of PAIRS) {
    const A = topics[ta];
    const B = topics[tb];
    /** @typedef {{ x: number, y: number, r: number, m: Node }} Placed */
    /** @type {(P: { x: number, y: number }, m: Node) => Placed} */
    const pos = (P, m) => ({ x: P.x + m.x * s, y: P.y + m.y * s, r: m.r * s, m });
    const na = A.nodes.map((m) => pos(at[ta], m));
    const nb = B.nodes.map((m) => pos(at[tb], m));
    const all = na.concat(nb);
    /** @type {[number, Placed, Placed][]} */
    const cand = [];
    /** @type {[Placed, Placed][]} */
    const got = [];
    na.forEach((a) => {
      if (a.m.seed || a.m.deg > 7) return;
      nb.forEach((b) => {
        if (!b.m.seed && b.m.deg <= 7) cand.push([Math.hypot(a.x - b.x, a.y - b.y), a, b]);
      });
    });
    cand.sort((p, q) => p[0] - q[0]);
    for (let k = 0; k < cand.length && got.length < many; k++) {
      const a = cand[k][1];
      const b = cand[k][2];
      const ex = b.x - a.x;
      const ey = b.y - a.y;
      const el = ex * ex + ey * ey;
      const apart = got.every(
        (g) => Math.hypot(g[0].x - a.x, g[0].y - a.y) > 74 * s && Math.hypot(g[1].x - b.x, g[1].y - b.y) > 60 * s,
      );
      const clear = all.every((m) => {
        if (m === a || m === b) return true;
        const t = Math.max(0, Math.min(1, ((m.x - a.x) * ex + (m.y - a.y) * ey) / el));
        return Math.hypot(a.x + ex * t - m.x, a.y + ey * t - m.y) > m.r + 5;
      });
      if (apart && clear) got.push([a, b]);
    }
    for (const g of got) out.push([ta, g[0].m.i, tb, g[1].m.i]);
  }
  return out;
}
